@file:OptIn(InternalResourceApi::class)

package voctrust.shared.generated.resources

import kotlin.OptIn
import kotlin.String
import kotlin.collections.MutableMap
import org.jetbrains.compose.resources.DrawableResource
import org.jetbrains.compose.resources.InternalResourceApi
import org.jetbrains.compose.resources.ResourceItem

private const val MD: String = "composeResources/voctrust.shared.generated.resources/"

internal val Res.drawable.instagram: DrawableResource by lazy {
      DrawableResource("drawable:instagram", setOf(
        ResourceItem(setOf(), "${MD}drawable/instagram.webp", -1, -1),
      ))
    }

internal val Res.drawable.logo_voc: DrawableResource by lazy {
      DrawableResource("drawable:logo_voc", setOf(
        ResourceItem(setOf(), "${MD}drawable/logo_voc.webp", -1, -1),
      ))
    }

@InternalResourceApi
internal fun _collectCommonMainDrawable0Resources(map: MutableMap<String, DrawableResource>) {
  map.put("instagram", Res.drawable.instagram)
  map.put("logo_voc", Res.drawable.logo_voc)
}
